#include <filesystem>
#include <fstream>
#include <iostream>
#include "ddb/buffer/buffer_pool_manager.h"
#include "ddb/storage/page_manager.h"
using namespace ddb::storage;
int main(){auto p=std::filesystem::temp_directory_path()/"ddb_page_allocation_state.db";std::error_code e;std::filesystem::remove(p,e);try{{PageManager m(p);auto a=m.allocate_page(),b=m.allocate_page();(void)b;ddb::buffer::BufferPoolManager bp(m,2);auto*x=bp.fetch_page(a);if(!x||!bp.unpin_page(a,false))throw std::runtime_error("cache setup");m.deallocate_page(a);if(m.is_page_allocated(a)||m.allocated_page_count()!=1)throw std::runtime_error("deallocation");try{(void)bp.fetch_page(a);throw std::runtime_error("cached free page fetched");}catch(const StorageError&){}Page q;try{m.read_page(a,q);throw std::runtime_error("free page read");}catch(const StorageError&){}m.flush();}{PageManager m(p);if(m.page_count()!=2||m.allocated_page_count()!=1||m.is_page_allocated(PageId(0))||!m.is_page_allocated(PageId(1)))throw std::runtime_error("persistence");}for(auto off:{std::streamoff(0),std::streamoff(4),std::streamoff(8)}){std::filesystem::remove(p,e);{PageManager m(p);(void)m.allocate_page();m.flush();}{std::fstream f(p,std::ios::binary|std::ios::in|std::ios::out);f.seekp(off);char z=0;f.write(&z,1);}try{PageManager m(p);throw std::runtime_error("corrupt catalog accepted");}catch(const StorageError&){}}std::filesystem::remove(p,e);std::cout<<"All page allocation state tests passed\n";}catch(const std::exception& x){std::cerr<<x.what()<<'\n';return 1;}}
